(function(){"use strict";const o=window.OasisAuth,l=new URLSearchParams(location.search).get("next");function r(t){t.rol==="master"?location.href="admin.html":t.rol==="atendedor"?location.href="atencion.html":location.href=l||"mis-vehiculos.html"}function n(t){const e=document.getElementById("authError");e.textContent=t}document.getElementById("tabLogin").onclick=()=>{document.getElementById("tabLogin").classList.add("on"),document.getElementById("tabRegister").classList.remove("on"),document.getElementById("loginForm").style.display="grid",document.getElementById("registerForm").style.display="none",document.getElementById("authTitle").textContent="Ingresar",document.getElementById("authSub").textContent="Entra con tu c\xE9dula para ver tus veh\xEDculos reservados.",n("")},document.getElementById("tabRegister").onclick=()=>{document.getElementById("tabRegister").classList.add("on"),document.getElementById("tabLogin").classList.remove("on"),document.getElementById("registerForm").style.display="grid",document.getElementById("loginForm").style.display="none",document.getElementById("authTitle").textContent="Crear usuario",document.getElementById("authSub").textContent="Reg\xEDstrate con tu c\xE9dula para guardar tus reservas.",n("")},document.getElementById("loginForm").onsubmit=t=>{t.preventDefault(),n("");const e=o.login(document.getElementById("lCedula").value,document.getElementById("lPass").value);if(!e.ok){n(e.error);return}r(e.user)},document.getElementById("registerForm").onsubmit=t=>{t.preventDefault(),n("");const e=o.register({nombre:document.getElementById("rNombre").value.trim(),cedula:document.getElementById("rCedula").value.trim(),telefono:document.getElementById("rTel").value.trim(),email:document.getElementById("rEmail").value.trim(),pass:document.getElementById("rPass").value});if(!e.ok){n(e.error);return}r(e.user)}})();
